-- Fix: Update payment_receipt template subject line and HTML padding
-- The previous migration 20260511000003 had no body padding and a generic subject.

BEGIN;

-- Update the default master template
UPDATE public.default_email_templates
SET
  subject_template = 'Payment Receipt #{{receipt_number}} — {{confirmation_number}} · {{property_name}}',
  html_template = '<!DOCTYPE html><html xmlns="http://www.w3.org/1999/xhtml" style="margin:0;padding:0;"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><style type="text/css">html,body{width:100%!important;margin:0!important;padding:0!important;min-height:100%!important;background-color:#f0f0f0!important;}table{border-collapse:collapse;mso-table-lspace:0pt;mso-table-rspace:0pt;}</style></head><body bgcolor="#f0f0f0" style="margin:0;padding:0;width:100%!important;min-height:100%;height:100%;background-color:#f0f0f0;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,''Helvetica Neue'',Ubuntu,sans-serif;"><table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" bgcolor="#f0f0f0" style="width:100%;min-height:100%;background-color:#f0f0f0;mso-table-lspace:0pt;mso-table-rspace:0pt;"><tr><td align="center" valign="top" bgcolor="#f0f0f0" style="width:100%;background-color:#f0f0f0;vertical-align:top;"><table role="presentation" width="640" cellspacing="0" cellpadding="0" border="0" style="max-width:640px;margin:0 auto;background-color:#ffffff;"><tr><td style="padding:32px 40px 48px;"><!-- Header: company left --><table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0"><tr><td style="vertical-align:top;width:58%;"><p style="margin:0 0 4px;font-size:15px;font-weight:700;color:#111;line-height:22px;">{{property_name}}</p>{{property_address_lines_html}}</td><td style="vertical-align:top;width:42%;text-align:right;"> </td></tr></table><!-- Divider --><hr style="border-color:#ddd;margin:20px 0;"><!-- Document title --><p style="margin:0;padding:8px 0 0;text-align:right;color:#111;font-size:22px;font-weight:800;letter-spacing:0.04em;text-transform:uppercase;">{{document_title}}</p><!-- Billed to + receipt meta --><table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="padding:24px 0 0;"><tr><td style="vertical-align:top;width:50%;padding-right:16px;"><p style="margin:0 0 8px;font-size:13px;font-weight:700;color:#111;">Billed to</p><p style="margin:0;font-size:13px;line-height:20px;color:#333;white-space:pre-line;">{{billed_to}}</p></td><td style="vertical-align:top;width:50%;text-align:right;"><table role="presentation" cellspacing="0" cellpadding="0" border="0" style="margin-left:auto;"><tr><td style="font-size:12px;font-weight:700;color:#333;padding:4px 12px 4px 0;text-align:right;vertical-align:top;">Receipt #</td><td style="font-size:12px;color:#111;padding:4px 0;text-align:right;vertical-align:top;">{{receipt_number}}</td></tr><tr><td style="font-size:12px;font-weight:700;color:#333;padding:4px 12px 4px 0;text-align:right;vertical-align:top;">Confirmation</td><td style="font-size:12px;color:#111;padding:4px 0;text-align:right;vertical-align:top;">{{confirmation_number}}</td></tr><tr><td style="font-size:12px;font-weight:700;color:#333;padding:4px 12px 4px 0;text-align:right;vertical-align:top;">Receipt date</td><td style="font-size:12px;color:#111;padding:4px 0;text-align:right;vertical-align:top;">{{receipt_date}}</td></tr></table></td></tr></table><!-- Intro text --><p style="margin:0;padding:0;margin-top:28px;color:#555;font-size:13px;line-height:20px;">The following charges are on your account. This receipt reflects the payment recorded today.</p><!-- Line items table --><table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="padding:16px 0 0;"><tr><td><table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="border:1px solid #ddd;border-collapse:collapse;"><thead><tr><th style="background-color:#3d3d3d;color:#fff;font-size:11px;font-weight:700;letter-spacing:0.06em;padding:10px 12px;text-align:left;text-transform:uppercase;width:44px;">QTY</th><th style="background-color:#3d3d3d;color:#fff;font-size:11px;font-weight:700;letter-spacing:0.06em;padding:10px 12px;text-align:left;text-transform:uppercase;">Description</th><th style="background-color:#3d3d3d;color:#fff;font-size:11px;font-weight:700;letter-spacing:0.06em;padding:10px 12px;text-align:right;text-transform:uppercase;width:96px;">Unit price</th><th style="background-color:#3d3d3d;color:#fff;font-size:11px;font-weight:700;letter-spacing:0.06em;padding:10px 12px;text-align:right;text-transform:uppercase;width:96px;">Amount</th></tr></thead><tbody>{{line_items_html}}</tbody></table></td></tr></table><!-- Divider light --><hr style="border-color:#e5e5e5;margin:0 0 16px;"><!-- Totals --><table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="padding:8px 0 0;"><tr><td><table role="presentation" cellspacing="0" cellpadding="0" border="0" style="width:100%;max-width:280px;margin-left:auto;"><tr><td style="color:#555;font-size:13px;padding:6px 12px 6px 0;">Charges subtotal</td><td style="color:#111;font-size:13px;padding:6px 0;text-align:right;">{{subtotal}}</td></tr><tr><td style="color:#555;font-size:13px;padding:6px 12px 6px 0;">Amount paid (this receipt)</td><td style="color:#111;font-size:13px;padding:6px 0;text-align:right;font-weight:700;">{{amount_paid}}</td></tr><tr><td style="color:#555;font-size:13px;padding:6px 12px 6px 0;">Payment method</td><td style="color:#111;font-size:13px;padding:6px 0;text-align:right;">{{payment_method_label}}<span style="color:#777;font-weight:400;"> · {{payment_source_label}}</span></td></tr><tr><td style="color:#111;font-size:13px;padding:12px 12px 6px 0;font-weight:700;border-top:1px solid #ccc;">Remaining balance</td><td style="color:#111;font-size:15px;padding:12px 0 6px;text-align:right;font-weight:800;border-top:1px solid #ccc;">{{remaining_balance}}</td></tr></table></td></tr></table><!-- Double divider --><hr style="border-color:#111;border-top-width:2px;margin:8px 0 24px;"><!-- Notes --><table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0"><tr><td><p style="margin:0 0 8px;font-size:13px;font-weight:700;color:#111;">Notes</p><p style="margin:0 0 8px;font-size:13px;line-height:21px;color:#444;">Thank you for your payment. Please retain this receipt for your records. If you have questions about charges or payments, contact {{property_name}}{{property_contact_info}}.</p>{{reservation_totals_note}}</td></tr></table></td></tr></table></td></tr></table></body></html>',
  version = version + 1,
  updated_at = now()
WHERE slug = 'payment_receipt';

-- Update the backfilled company-level templates
UPDATE public.email_templates
SET
  subject_template = 'Payment Receipt #{{receipt_number}} — {{confirmation_number}} · {{property_name}}',
  html_template = '<!DOCTYPE html><html xmlns="http://www.w3.org/1999/xhtml" style="margin:0;padding:0;"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><style type="text/css">html,body{width:100%!important;margin:0!important;padding:0!important;min-height:100%!important;background-color:#f0f0f0!important;}table{border-collapse:collapse;mso-table-lspace:0pt;mso-table-rspace:0pt;}</style></head><body bgcolor="#f0f0f0" style="margin:0;padding:0;width:100%!important;min-height:100%;height:100%;background-color:#f0f0f0;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,''Helvetica Neue'',Ubuntu,sans-serif;"><table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" bgcolor="#f0f0f0" style="width:100%;min-height:100%;background-color:#f0f0f0;mso-table-lspace:0pt;mso-table-rspace:0pt;"><tr><td align="center" valign="top" bgcolor="#f0f0f0" style="width:100%;background-color:#f0f0f0;vertical-align:top;"><table role="presentation" width="640" cellspacing="0" cellpadding="0" border="0" style="max-width:640px;margin:0 auto;background-color:#ffffff;"><tr><td style="padding:32px 40px 48px;"><!-- Header: company left --><table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0"><tr><td style="vertical-align:top;width:58%;"><p style="margin:0 0 4px;font-size:15px;font-weight:700;color:#111;line-height:22px;">{{property_name}}</p>{{property_address_lines_html}}</td><td style="vertical-align:top;width:42%;text-align:right;"> </td></tr></table><!-- Divider --><hr style="border-color:#ddd;margin:20px 0;"><!-- Document title --><p style="margin:0;padding:8px 0 0;text-align:right;color:#111;font-size:22px;font-weight:800;letter-spacing:0.04em;text-transform:uppercase;">{{document_title}}</p><!-- Billed to + receipt meta --><table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="padding:24px 0 0;"><tr><td style="vertical-align:top;width:50%;padd