 style="background-color:#3d3d3d;color:#fff;font-size:11px;font-weight:700;letter-spacing:0.06em;padding:10px 12px;text-align:right;text-transform:uppercase;width:96px;">Unit price</th><th style="background-color:#3d3d3d;color:#fff;font-size:11px;font-weight:700;letter-spacing:0.06em;padding:10px 12px;text-align:right;text-transform:uppercase;width:96px;">Amount</th></tr></thead><tbody>{{line_items_html}}</tbody></table></td></tr></table><!-- Divider light --><hr style="border-color:#e5e5e5;margin:0 0 16px;"><!-- Totals --><table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="padding:8px 0 0;"><tr><td><table role="presentation" cellspacing="0" cellpadding="0" border="0" style="width:100%;max-width:280px;margin-left:auto;"><tr><td style="color:#555;font-size:13px;padding:6px 12px 6px 0;">Charges subtotal</td><td style="color:#111;font-size:13px;padding:6px 0;text-align:right;">{{subtotal}}</td></tr><tr><td style="color:#555;font-size:13px;padding:6px 12px 6px 0;">Amount paid (this receipt)</td><td style="color:#111;font-size:13px;padding:6px 0;text-align:right;font-weight:700;">{{amount_paid}}</td></tr><tr><td style="color:#555;font-size:13px;padding:6px 12px 6px 0;">Payment method</td><td style="color:#111;font-size:13px;padding:6px 0;text-align:right;">{{payment_method_label}}<span style="color:#777;font-weight:400;"> · {{payment_source_label}}</span></td></tr><tr><td style="color:#111;font-size:13px;padding:12px 12px 6px 0;font-weight:700;border-top:1px solid #ccc;">Remaining balance</td><td style="color:#111;font-size:15px;padding:12px 0 6px;text-align:right;font-weight:800;border-top:1px solid #ccc;">{{remaining_balance}}</td></tr></table></td></tr></table><!-- Double divider --><hr style="border-color:#111;border-top-width:2px;margin:8px 0 24px;"><!-- Notes --><table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0"><tr><td><p style="margin:0 0 8px;font-size:13px;font-weight:700;color:#111;">Notes</p><p style="margin:0 0 8px;font-size:13px;line-height:21px;color:#444;">Thank you for your payment. Please retain this receipt for your records. If you have questions about charges or payments, contact {{property_name}}{{property_contact_info}}.</p>{{reservation_totals_note}}</td></tr></table></td></tr></table></td></tr></table></body></html>',
  is_modified = false,
  default_version = (SELECT version FROM public.default_email_templates WHERE slug = 'payment_receipt'),
  updated_at = now()
WHERE slug = 'payment_receipt'
  AND is_system_default = true;

COMMIT;
